def hasClosedTour(n, edges):
    if not edges:
        return True
    deg = [0] * n
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
    if any(d % 2 for d in deg):
        return False
    root = find(edges[0][0])
    return all(find(v) == root for v in range(n) if deg[v] > 0)
